package edu.pe.cibertec.saibm.inventario.infrastructure.persistence; import java.time.Instant; import java.util.UUID; import jakarta.persistence.*; import edu.pe.cibertec.saibm.inventario.domain.model.InventoryMovement; @Entity @Table(name="inventory_movements") public class MovementJpaEntity {@Id UUID id; @Column(name="book_id",nullable=false,length=200) String bookId; @Column(nullable=false) int delta; @Column(nullable=false,length=40) String reason; @Column(name="operation_key",nullable=false,length=200) String operationKey; @Column(name="occurred_at",nullable=false) Instant occurredAt; protected MovementJpaEntity(){} MovementJpaEntity(InventoryMovement m){id=m.id();bookId=m.bookId();delta=m.delta();reason=m.reason();operationKey=m.operationKey();occurredAt=m.occurredAt();} }
